create extension if not exists pgcrypto;
create table if not exists public.experts (id uuid primary key default gen_random_uuid(), full_name text not null, phone text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.cases (id uuid primary key default gen_random_uuid(), case_year integer not null, case_number integer not null, insured_name text not null, phone text not null, expert_id uuid references public.experts(id) on delete set null, description text, status text not null default 'needs_review', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(case_year, case_number));
create table if not exists public.case_deficiencies (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, title text not null, description text, is_resolved boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), resolved_at timestamptz, resolved_by uuid references auth.users(id) on delete set null);
create table if not exists public.case_expert_history (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete restrict, previous_expert_id uuid references public.experts(id) on delete set null, new_expert_id uuid references public.experts(id) on delete set null, changed_at timestamptz not null default now(), changed_by uuid references auth.users(id) on delete set null);
create table if not exists public.activity_logs (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, case_id uuid references public.cases(id) on delete set null, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists cases_search_idx on public.cases using gin (to_tsvector('simple', insured_name || ' ' || phone)); create index if not exists cases_year_idx on public.cases(case_year); create index if not exists deficiencies_case_idx on public.case_deficiencies(case_id, is_resolved); create index if not exists activity_case_idx on public.activity_logs(case_id, created_at desc);
alter table public.experts enable row level security; alter table public.cases enable row level security; alter table public.case_deficiencies enable row level security; alter table public.case_expert_history enable row level security; alter table public.activity_logs enable row level security;
create policy "authenticated experts access" on public.experts for all to authenticated using (true) with check (true); create policy "authenticated cases access" on public.cases for all to authenticated using (deleted_at is null) with check (true); create policy "authenticated deficiencies access" on public.case_deficiencies for all to authenticated using (true) with check (true); create policy "authenticated history read" on public.case_expert_history for select to authenticated using (true); create policy "authenticated history insert" on public.case_expert_history for insert to authenticated with check (true); create policy "authenticated activity access" on public.activity_logs for select to authenticated using (true); create policy "authenticated activity insert" on public.activity_logs for insert to authenticated with check (true);
